import { forwardRef } from "react";
import { clsx } from "clsx";
import ReactMarkdown from "react-markdown";
import { useTheme } from "@theme";

import {
  AIStepProps,
  AIStepTitleProps,
  AIStepSummaryProps,
  AIStepToolProps,
} from "./ai-step.types";
import { AIStepClasses, StyledAIStep } from "./ai-step.styles";

export const AIStep = forwardRef<HTMLDivElement, AIStepProps>(
  ({ className, children, variant = "default", ...props }, ref) => {
    const theme = useTheme();
    const rootClasses = clsx(AIStepClasses.step, className);

    return (
      <StyledAIStep
        ref={ref}
        className={rootClasses}
        currentTheme={theme}
        variant={variant}
        {...props}
      >
        {children}
      </StyledAIStep>
    );
  },
);

AIStep.displayName = "AI.Step";

export const AIStepTitle = forwardRef<HTMLDivElement, AIStepTitleProps>(
  ({ className, children, ...props }, ref) => {
    return (
      <div ref={ref} className={clsx(AIStepClasses.title, className)} {...props}>
        {children}
      </div>
    );
  },
);

AIStepTitle.displayName = "AI.StepTitle";

export const AIStepSummary = forwardRef<HTMLDivElement, AIStepSummaryProps>(
  ({ className, children, markdown = true, ...props }, ref) => {
    return (
      <div ref={ref} className={clsx(AIStepClasses.summary, className)} {...props}>
        {markdown && typeof children === "string" ? (
          <ReactMarkdown>{children}</ReactMarkdown>
        ) : (
          children
        )}
      </div>
    );
  },
);

AIStepSummary.displayName = "AI.StepSummary";

export const AIStepTool = forwardRef<HTMLDivElement, AIStepToolProps>(
  ({ className, children, ...props }, ref) => {
    return (
      <div ref={ref} className={clsx(AIStepClasses.tool, className)} {...props}>
        {children}
      </div>
    );
  },
);

AIStepTool.displayName = "AI.StepTool";
